use crate::git::get_git_hooks_dir;
use std::fs;

const HOOK_SCRIPT: &str = r#"#!/bin/sh
# EnvGuard Git Pre-Commit Hook
# Automatically generated by `envguard install-hook`

envguard scan
"#;

pub fn install_pre_commit_hook() -> Result<(), String> {
    // Map typed GitError to a human-readable String for the CLI error display
    let hooks_dir = get_git_hooks_dir().map_err(|e| e.to_string())?;
    let hook_path = hooks_dir.join("pre-commit");

    if !hooks_dir.exists() {
        fs::create_dir_all(&hooks_dir)
            .map_err(|e| format!("Failed to create hooks directory: {}", e))?;
    }

    if hook_path.exists() {
        return Err(format!(
            "A pre-commit hook already exists at {}. Remove or backup the existing file before running install-hook.",
            hook_path.display()
        ));
    }

    fs::write(&hook_path, HOOK_SCRIPT)
        .map_err(|e| format!("Failed to write hook script: {}", e))?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(&hook_path)
            .map_err(|e| format!("Failed to read hook permissions: {}", e))?
            .permissions();
        perms.set_mode(0o755);
        fs::set_permissions(&hook_path, perms)
            .map_err(|e| format!("Failed to set executable permissions: {}", e))?;
    }

    println!(
        "Successfully installed EnvGuard pre-commit hook at {}",
        hook_path.display()
    );
    Ok(())
}
